UNITS = [{"id": "PEDS-U032", "ch": 4, "n": 32, "title": "Clinical Features of Respiratory Distress", "sec": "Clinical Features · p16", "guide": "Clinical features: 1. Respiratory rate increased (>60 breaths/min; normal newborn RR 40-60/min). 2. Chest retraction: d/t involvement of accessory respiratory muscles. 3. Severe hypoxia (severe cases): central cyanosis (involves mucosa as well), grunting (expiration against partially closed glottis -> prevents airway/alveolar collapse). (Book p16)", "qs": ["PEDS-C4-001", "PEDS-C4-002", "PEDS-C4-003", "PEDS-C4-004", "PEDS-C4-005", "PEDS-C4-006", "PEDS-C4-007"]}, {"id": "PEDS-U033", "ch": 4, "n": 33, "title": "Silverman Anderson Score", "sec": "Silverman Anderson Score · p16", "guide": "Used for preterm babies. 5 criteria scored 0/1/2: upper chest retraction (0 synchronized chest-abdomen, 1 lag, 2 see-saw), lower chest retraction, nasal flaring, xiphoid retractions (not seen/mild/severe), grunting (not present/audible with stethoscope/audible without). Interpretation: <5 mild, 5-7 moderate, >7 severe. (Book p16)", "qs": ["PEDS-C4-008", "PEDS-C4-009", "PEDS-C4-010", "PEDS-C4-011", "PEDS-C4-012", "PEDS-C4-013", "PEDS-C4-014", "PEDS-C4-015", "PEDS-C4-016", "PEDS-C4-017"]}, {"id": "PEDS-U034", "ch": 4, "n": 34, "title": "Downe's Score", "sec": "Downe's Score · p16", "guide": "Used for term and preterm babies. Mnemonic for criteria: CRAG (Cyanosis, Respiratory rate, Air entry, Grunting). Scored 0/1/2. Interpretation: <3 mild, 4-6 moderate, >6 severe (impending respiratory failure). (Book p16)", "qs": ["PEDS-C4-018", "PEDS-C4-019", "PEDS-C4-020", "PEDS-C4-021", "PEDS-C4-022", "PEDS-C4-023", "PEDS-C4-024", "PEDS-C4-025", "PEDS-C4-026", "PEDS-C4-027", "PEDS-C4-028", "PEDS-C4-029", "PEDS-C4-030"]}, {"id": "PEDS-U035", "ch": 4, "n": 35, "title": "Causes of Respiratory Distress", "sec": "Causes of Respiratory Distress · p17", "guide": "Onset within 6 hours of birth: TTNB (m/c overall), RDS, meconium aspiration syndrome. Onset any time after birth: pneumonia, pneumothorax. Also: anomalies of lung development. (Book p17)", "qs": ["PEDS-C4-031", "PEDS-C4-032", "PEDS-C4-033", "PEDS-C4-034"]}, {"id": "PEDS-U036", "ch": 4, "n": 36, "title": "TTNB: Transient Tachypnea of Newborn", "sec": "TTNB · p17", "guide": "AKA wet lung syndrome. m/c in term neonates and neonates delivered by LSCS. Pathogenesis: term neonate -> adequate stimulation and compression at birth (birth canal) -> clearance of lung fluids; without it -> delayed clearance of lung fluids. CXR: perihilar radio-opaque streaks (fluid in hilium -> bronchovascular structures -> white streaks, AKA sunburst appearance); fluid in interlobar fissure. Management: supportive (O2 inhalation) sufficient (transient); improvement in 48-72 hours. (Book p17)", "qs": ["PEDS-C4-035", "PEDS-C4-036", "PEDS-C4-037", "PEDS-C4-038", "PEDS-C4-039", "PEDS-C4-040", "PEDS-C4-041", "PEDS-C4-042", "PEDS-C4-043", "PEDS-C4-044", "PEDS-C4-045"]}, {"id": "PEDS-U037", "ch": 4, "n": 37, "title": "RDS: Hyaline Membrane Disease", "sec": "RDS · p17", "guide": "AKA hyaline membrane disease (HMD). m/c in preterm (<34 wks) born to mothers who haven't received antenatal steroids (m/c: dexamethasone) and infants of diabetic mothers (up insulin -> down surfactant). Down surfactant -> up surface tension -> alveolar collapse and respiratory distress. Surfactant keeps alveoli open by decreasing surface tension. Histology: eosinophilic substances in lung tissue (resembles hyaline). CXR: white out/ground glass (collapsed alveoli, no air entry); air bronchogram sign (open airway tract). (Book p17-18)", "qs": ["PEDS-C4-046", "PEDS-C4-047", "PEDS-C4-048", "PEDS-C4-049", "PEDS-C4-050", "PEDS-C4-051", "PEDS-C4-052", "PEDS-C4-053", "PEDS-C4-054", "PEDS-C4-055", "PEDS-C4-056"]}, {"id": "PEDS-U038", "ch": 4, "n": 38, "title": "RDS: Management & Surfactant", "sec": "Management (RDS) · p18", "guide": "Severity by Silverman score: mild (<5) and moderate (5-7) -> CPAP (PEEP of 5-7 mm H2O maintained -> keeps alveoli open); severe (>7) -> mechanical ventilation; surfactant replacement therapy. SRT types: natural (beractant bovine, poractant pigs), recombinant synthetic (with SP-B). Administration: endotracheal; technique: ET tube (mnemonic INSURE: intubation, surfactant, extubation) or surfactant tracheal catheter (STC) - less invasive. Earlier synthetic surfactants leaked SP-B -> down efficacy. (Book p18)", "qs": ["PEDS-C4-057", "PEDS-C4-058", "PEDS-C4-059", "PEDS-C4-060", "PEDS-C4-061", "PEDS-C4-062", "PEDS-C4-063", "PEDS-C4-064", "PEDS-C4-065", "PEDS-C4-066", "PEDS-C4-067", "PEDS-C4-068"]}, {"id": "PEDS-U039", "ch": 4, "n": 39, "title": "Meconium Aspiration Syndrome (MAS)", "sec": "MAS · p19", "guide": "Pathogenesis: post-term baby (>42 wks) / IUGR baby stress -> meconium expulsion before birth -> aspiration of meconium stained liquor (MSL). Consequences: 1. Atelectasis (d/t complete airway obstruction); 2. Air trapping (partial obstruction) -> hyperinflation/obstructive emphysema; 3. Chemical pneumonitis -> inactivation of surfactant -> impaired gas exchange -> hypoxia, hypercapnia -> chronic pulmonary vasoconstriction -> PPHN. CXR: infiltrates in lung field. Diagnosis: by exclusion + with h/o MSL. Management: supportive (O2, CPAP, MV in severe); inhaled nitric oxide (iNO): pulmonary vasodilator for PPHN. (Book p19)", "qs": ["PEDS-C4-069", "PEDS-C4-070", "PEDS-C4-071", "PEDS-C4-072", "PEDS-C4-073", "PEDS-C4-074", "PEDS-C4-075", "PEDS-C4-076", "PEDS-C4-077", "PEDS-C4-078", "PEDS-C4-079", "PEDS-C4-080", "PEDS-C4-081"]}, {"id": "PEDS-U040", "ch": 4, "n": 40, "title": "Congenital Diaphragmatic Hernia (CDH)", "sec": "CDH · p19", "guide": "Pathogenesis: anatomical defect in diaphragm. Types: Bochdalek (m/c, postero-lateral), Morgagni (antero-medial). Features: respiratory distress (compression of lung in utero d/t movement of intestines into mediastinum -> pulmonary hypoplasia), mediastinal shift -> heart sound heard on right side, sunken/scaphoid abdomen. Investigations: USG antenatal; CXR postnatal (intestinal air shadows, absent diaphragm shadow on affected side). Management: no cry at birth -> resuscitation; cries: medical (first 48 hrs: NG tube -> down lung compression, MV via ET tube -> up lung expansion) then surgical (>48 hrs: hernia repair). CDH is absolute C/I for bag and mask ventilation (air into esophagus -> bowel loop inflation -> lung compression). Prognosis: antenatal USG LHR <1 and liver in thorax bad; postnatal PPHN (most important) and onset of distress <24 hrs bad. (Book p19-20)", "qs": ["PEDS-C4-082", "PEDS-C4-083", "PEDS-C4-084", "PEDS-C4-085", "PEDS-C4-086", "PEDS-C4-087", "PEDS-C4-088", "PEDS-C4-089", "PEDS-C4-090", "PEDS-C4-091", "PEDS-C4-092", "PEDS-C4-093", "PEDS-C4-094", "PEDS-C4-095", "PEDS-C4-096", "PEDS-C4-097", "PEDS-C4-098", "PEDS-C4-099", "PEDS-C4-100", "PEDS-C4-101"]}]

def q(num, sec, page, qtext, opts, ans, exp):
    assert len(opts)==4 and 0 <= ans <4
    return {"id": f"PEDS-C4-{num:03d}", "sec": sec, "page": page, "q": qtext, "opts": opts, "ans": ans, "exp": exp}

